AS=r'''#include <bits/stdc++.h>
using namespace std;const int N=18;unsigned long long a[N],b[64],c[64];int w[N],o[N];int main(int z,char**v){ios::sync_with_stdio(0);cin.tie(0);int R=z>1?stoi(v[1]):1000;unsigned long long s=z>2?stoull(v[2]):1;mt19937_64 g(s);while(R--){int n=g()%14+1;for(int i=0;i<n;i++)a[i]=g()%1024+1,w[i]=g()%100+1;iota(o,o+n,0);sort(o,o+n,[](int x,int y){return w[x]>w[y];});memset(b,0,sizeof b);long long x=0,y=0;for(int j=0;j<n;j++){auto q=a[o[j]];for(int i=63;i>=0;i--)if(q>>i&1){if(b[i])q^=b[i];else{b[i]=q;x+=w[o[j]];break;}}}for(int m=0;m<(1<<n);m++){memset(c,0,sizeof c);long long q=0;bool f=1;for(int j=0;j<n&&f;j++)if(m>>j&1){auto t=a[j];bool k=0;q+=w[j];for(int i=63;i>=0;i--)if(t>>i&1){if(c[i])t^=c[i];else{c[i]=t;k=1;break;}}if(!k)f=0;}if(f)y=max(y,q);}if(x!=y)return cout<<"WA\n",1;}cout<<"OK\n";}
'''
add('P4570','P4570 [BJWC2011] 元素',r'把矿石按魔力从大到小排序，依次尝试加入异或线性基。线性无关集合构成线性拟阵，因此该贪心得到最大权独立集。时间复杂度 $O(64N+N\log N)$。',{'.cpp':A,' 数据生成.cpp':AG,' 暴力.cpp':AB,' 对拍.cpp':AS},extra=[('1\n7 9\n','9\n'),('3\n1 5\n2 4\n3 100\n','105\n'),('4\n1 1\n2 2\n4 4\n7 20\n','26\n')])

B=r'''#include <bits/stdc++.h>
using namespace std;const int N=20005,L=15;unsigned long long a[N],b[N][61],c[61];int h[N],to[N*2],nx[N*2],p[N][L],d[N],z[N][61],q[N],e;void I(unsigned long long*x,int*y,unsigned long long v,int k){for(int i=60;i>=0;i--)if(v>>i&1){if(!x[i]){x[i]=v;y[i]=k;return;}if(y[i]<k)swap(y[i],k),swap(x[i],v);v^=x[i];}}void J(unsigned long long v){for(int i=60;i>=0;i--)if(v>>i&1){if(c[i])v^=c[i];else{c[i]=v;return;}}}int lca(int x,int y){if(d[x]<d[y])swap(x,y);for(int i=L-1;i>=0;i--)if(d[p[x][i]]>=d[y])x=p[x][i];if(x==y)return x;for(int i=L-1;i>=0;i--)if(p[x][i]!=p[y][i])x=p[x][i],y=p[y][i];return p[x][0];}int main(){ios::sync_with_stdio(0);cin.tie(0);int n,m;cin>>n>>m;for(int i=1;i<=n;i++)cin>>a[i];for(int i=1,u,v;i<n;i++){cin>>u>>v;to[++e]=v;nx[e]=h[u];h[u]=e;to[++e]=u;nx[e]=h[v];h[v]=e;}int l=0,r=1;q[0]=1;d[1]=1;while(l<r){int u=q[l++];for(int i=h[u];i;i=nx[i])if(to[i]!=p[u][0])p[to[i]][0]=u,d[to[i]]=d[u]+1,q[r++]=to[i];}for(int k=0;k<n;k++){int u=q[k],v=p[u][0];memcpy(b[u],b[v],sizeof b[u]);memcpy(z[u],z[v],sizeof z[u]);I(b[u],z[u],a[u],d[u]);for(int j=1;j<L;j++)p[u][j]=p[p[u][j-1]][j-1];}while(m--){int x,y;cin>>x>>y;int t=lca(x,y);memset(c,0,sizeof c);for(int i=60;i>=0;i--){if(z[x][i]>=d[t])J(b[x][i]);if(z[y][i]>=d[t])J(b[y][i]);}unsigned long long s=0;for(int i=60;i>=0;i--)s=max(s,s^c[i]);cout<<s<<'\n';}}
'''
BB=r'''#include <bits/stdc++.h>
using namespace std;const int N=1005;unsigned long long a[N],b[61];int h[N],to[N*2],nx[N*2],p[N],q[N],e;int main(){ios::sync_with_stdio(0);cin.tie(0);int n,m;cin>>n>>m;for(int i=1;i<=n;i++)cin>>a[i];for(int i=1,u,v;i<n;i++){cin>>u>>v;to[++e]=v;nx[e]=h[u];h[u]=e;to[++e]=u;nx[e]=h[v];h[v]=e;}while(m--){int x,y,l=0,r=1;q[0]=x;memset(p,0,sizeof p);p[x]=-1;while(l<r&&q[l]!=y){int u=q[l++];for(int i=h[u];i;i=nx[i])if(!p[to[i]])p[to[i]]=u,q[r++]=to[i];}memset(b,0,sizeof b);for(int u=y;u!=-1;u=p[u]){auto v=a[u];for(int i=60;i>=0;i--)if(v>>i&1){if(b[i])v^=b[i];else{b[i]=v;break;}}}unsigned long long s=0;for(int i=60;i>=0;i--)s=max(s,s^b[i]);cout<<s<<'\n';}}
'''
