CS=r'''#include <bits/stdc++.h>
using namespace std;const int N=20,M=100;int h[N],to[M],nx[M],w[M],q[N*128],z[N*128],e;unsigned long long d[N],b[64];bool V[N],s[N][128];void I(unsigned long long x){for(int i=63;i>=0;i--)if(x>>i&1){if(b[i])x^=b[i];else{b[i]=x;return;}}}int main(int C,char**v){ios::sync_with_stdio(0);cin.tie(0);int R=C>1?stoi(v[1]):1000;unsigned long long S=C>2?stoull(v[2]):1;mt19937_64 g(S);while(R--){int n=g()%10+2,m=n-1+g()%15;e=0;memset(h,0,sizeof h);memset(V,0,sizeof V);memset(b,0,sizeof b);memset(s,0,sizeof s);auto E=[&](int x,int y,int k){to[++e]=y;w[e]=k;nx[e]=h[x];h[x]=e;to[++e]=x;w[e]=k;nx[e]=h[y];h[y]=e;};for(int i=2;i<=n;i++)E(i,g()%(i-1)+1,g()%64);while(e/2<m)E(g()%n+1,g()%n+1,g()%64);int l=0,r=1;q[0]=1;V[1]=1;while(l<r){int x=q[l++];for(int i=h[x];i;i=nx[i])if(!V[to[i]])V[to[i]]=1,d[to[i]]=d[x]^w[i],q[r++]=to[i];else I(d[x]^d[to[i]]^w[i]);}unsigned long long A=d[n];for(int i=63;i>=0;i--)A=max(A,A^b[i]);l=0;r=1;q[0]=1;z[0]=0;s[1][0]=1;while(l<r){int x=q[l],k=z[l++];for(int i=h[x];i;i=nx[i])if(!s[to[i]][k^w[i]])s[to[i]][k^w[i]]=1,q[r]=to[i],z[r++]=k^w[i];}int B=127;while(!s[n][B])B--;if(A!=(unsigned)B)return cout<<"WA\n",1;}cout<<"OK\n";}
'''
add('P4151','P4151 [WC2011] 最大 XOR 和路径',r'先求一棵生成树上的根异或距离 $d_u$。每条边产生一个环异或值 $d_u\oplus d_v\oplus w$，把这些值加入线性基；任意从 $1$ 到 $N$ 的游走等价于树路径异或值再异或若干环，最后从高位到低位贪心增大答案。时间复杂度 $O((N+M)\cdot64)$。',{'.cpp':C,' 数据生成.cpp':CG,' 暴力.cpp':CB,' 对拍.cpp':CS},parts=[CB],extra=[('2 1\n1 2 7\n','7\n'),('3 3\n1 2 1\n2 3 2\n1 3 4\n','4\n'),('2 2\n1 2 5\n1 1 7\n','5\n')])
